sql_gerado:
SELECT SUM(execucao_mensal.valor_pago) AS total_pago
FROM execucao_mensal
WHERE ano = 2025 AND categoria_economica = 'DESPESAS CORRENTES';

SELECT SUM(execucao_mensal.valor_pago) AS total_pago_emendas
FROM execucao_mensal
WHERE ano = 2025 AND com_emenda = TRUE;

SELECT SUM(valor_atualizado - valor_inicial) AS diferenca_total
FROM orcamento
WHERE ano = 2025;

SELECT SUM(valor_restos_a_pagar_cancelados) AS total_restos_cancelados
FROM execucao_mensal
WHERE ano = 2025;

SELECT COUNT(DISTINCT municipio) AS num_municipios
FROM execucao_mensal
WHERE ano = 2025 AND valor_pago > 0;

SELECT SUM(valor_liquidado) AS valor_total_liquidado
FROM execucao_mensal
WHERE ano = 2025;

SELECT AVG(valor_pago) AS media_mensal_pago
FROM execucao_mensal
WHERE ano = 2025;

SELECT SUM(execucao_mensal.valor_pago) AS total_pago_despesas_de_capital
FROM execucao_mensal
WHERE ano = 2025 AND categoria_economica = 'DESPESAS DE CAPITAL';

SELECT COUNT(DISTINCT codigo_unidade_gestora) AS num_unidades_gestoras
FROM execucao_mensal
WHERE ano = 2025 AND valor_pago > 0;

SELECT SUM(CASE WHEN valor_restos_a_pagar_inscritos > 0 THEN valor_restos_a_pagar_inscritos ELSE 0 END) - SUM(CASE WHEN valor_restos_a_pagar_inscritos < 0 THEN valor_restos_a_pagar_inscritos ELSE 0 END) AS saldo_liquido
FROM execucao_mensal
WHERE ano = 2025;

SELECT SUM(execucao_mensal.valor_empenhado) AS total_empenhado
FROM execucao_mensal
WHERE ano = 2025 AND categoria_economica = 'DESPESAS DE CAPITAL';

SELECT SUM(execucao_mensal.valor_pago) AS total_pago_transferencias_municipios
FROM execucao_mensal
WHERE ano = 2025 AND modalidade_despesa = 'Transferências a Municípios';

SELECT SUM(execucao_mensal.valor_pago) AS total_pago
FROM execucao_mensal
WHERE ano = 2025 AND uf IN ('DF', 'ES');
